## Service Interface

```typescript
interface CanonicalReferenceService {
  // Get canonical for a category
  getCanonical(
    category: "mascot" | "setting" | "typography" | "texture",
    name?: string
  ): Effect<CanonicalReference, NotFoundError>;

  // Get the canonical asset itself
  getCanonicalAsset(
    canonicalId: string
  ): Effect<Asset, NotFoundError>;

  // Get appropriate variant for context
  getVariantForContext(
    canonicalId: string,
    context: AlbumContext | MoodContext
  ): Effect<Asset, NotFoundError>;

  // Register a new canonical (user action)
  registerCanonical(
    asset: Asset,
    definition: CanonicalReference
  ): Effect<CanonicalReference, RegistrationError>;

  // Add variant to canonical
  addVariant(
    canonicalId: string,
    variant: Asset,
    useCase: string
  ): Effect<void, NotFoundError>;

  // Generate instance from canonical
  generateInstance(
    canonicalId: string,
    context: GenerationContext
  ): Effect<Asset, GenerationError>;
}
```

## Flow Integration

### Always-Seed Pattern

```typescript
// When generating Crate Cat for an album
const generateMascotForAlbum = (
  albumContext: AlbumContext,
  curationResult: CurationResult
) => Effect.gen(function* () {
  // 1. ALWAYS get the canonical reference
  const canonical = yield* CanonicalReference.getCanonical("mascot", "crate-cat");
  const canonicalAsset = yield* CanonicalReference.getCanonicalAsset(canonical.id);

  // 2. Check if a pre-made variant works
  const variant = yield* CanonicalReference.getVariantForContext(
    canonical.id,
    { palette: curationResult.palette, mood: curationResult.analysis.mood }
  ).pipe(Effect.option);

  if (Option.isSome(variant)) {
    // Use existing variant
    return variant.value;
  }

  // 3. Generate new instance, ALWAYS referencing canonical
  return yield* CanonicalReference.generateInstance(canonical.id, {
    albumContext,
    curationResult,
    referenceAsset: canonicalAsset, // ALWAYS included
    prompt: canonical.generationPromptTemplate
      .replace("[PALETTE]", curationResult.palette.colors.join(", "))
      .replace("[MOOD]", curationResult.analysis.moodAtmosphere)
      .replace("[ERA]", curationResult.analysis.eraAesthetic),
  });
});
```

### Upload Workflow

```bash
# 1. Upload canonical reference (one-time, sacred)
bun run src/scripts/upload-canonical.ts \
  --file ./crate-cat-original.png \
  --category mascot \
  --name "Crate Cat" \
  --description "The one true Crate Cat - curious music-loving cat mascot"

# 2. Upload variants
bun run src/scripts/upload-variant.ts \
  --file ./crate-cat-line-art.svg \
  --canonical crate-cat \
  --name "Line Art" \
  --useCase "overlays on busy album art"
```

