## Architecture

```typescript
// packages/agent/src/handoff/QueueHandoff.ts

interface AgentTask {
  taskType: "research" | "enrich" | "analyze"
  playId: number
  context: ResearchContext
  priority: "high" | "normal" | "low"
}

export const makeAgentQueue = Effect.gen(function* () {
  const queue = yield* Queue.bounded<AgentTask>(32)

  return {
    handoff: (task: AgentTask) => Queue.offer(queue, task),
    worker: (handler: (task: AgentTask) => Effect<void>) =>
      Effect.forever(
        Effect.gen(function* () {
          const task = yield* Queue.take(queue)
          yield* handler(task).pipe(
            Effect.retry({ times: 3, schedule: Schedule.exponential("100 millis") }),
            Effect.catchAll((error) =>
              Effect.logError("Task failed", { task, error })
            )
          )
        })
      )
  }
})
```

## Multi-Agent Pattern

```
┌─────────────┐     ┌─────────────┐
│ Coordinator │────►│ Work Queue  │
└─────────────┘     └──────┬──────┘
                           │
         ┌─────────────────┼─────────────────┐
         ▼                 ▼                 ▼
┌─────────────┐   ┌─────────────┐   ┌─────────────┐
│  Context    │   │  History    │   │ Connections │
│   Agent     │   │   Agent     │   │    Agent    │
└─────────────┘   └─────────────┘   └─────────────┘
```

## Estimated Effort
3-4 days

Move aspect ratio defaults into individual builders or use a style-specific default map:
```typescript
const styleDefaults = {
  "concert-poster": "portrait",
  "vinyl-sleeve": "square",
  // ...
};
const aspectRatio = request.aspectRatio ?? styleDefaults[style] ?? "square";
```

description:
Create a shared abstraction for building cacheable multi-agent prompts to ensure consistency.

**Location:** `/packages/agent/src/prompts/MultiAgentPrompt.ts`

**Interface:**
```typescript
export interface CacheableMultiAgentPrompt {
  staticContent: string;  // Cacheable portion
  dynamicContent: string; // Per-request
}

export const buildCacheablePrompt = (
  staticContent: string,
  dynamicContent: string
): Prompt.Prompt => Prompt.make([
  {
    role: "system",
    content: staticContent,
    options: { anthropic: { cacheControl: { type: "ephemeral" } } }
  },
  { role: "system", content: dynamicContent },
]);
```

**Benefits:**
- Consistent caching pattern across all agents
- Enforces static/dynamic split
- Reduces code duplication

