```typescript
const runWriter = (
  playIds: readonly number[],
  sessionExport: SessionExport
): Effect.Effect<{ insightCount: number }, CoordinatorError, LanguageModel> =>
  Effect.gen(function* () {
    currentStage = "writing";
    yield* Effect.log(`Writer: Crafting narratives for ${playIds.length} plays`);

    const writerOutputs = yield* writerAgent.writeBatch(playIds, sessionExport);

    const totalInsights = yield* Effect.forEach(
      writerOutputs,
      (output) => output.insights.length > 0
        ? faissClient.postInsights(output.insights, { session_id: sessionExport.sessionId })
        : Effect.succeed({ count: 0 }),
      { concurrency: 1 }
    );

    return { insightCount: totalInsights.reduce((a, b) => a + b.count, 0) };
  });
```

